import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync, writeFileSync } from 'node:fs'
import { startApp, tempDataFile, withApp } from './helpers.mjs'

const trip = { id: 'trip', name: 'Ski trip', members: ['Ann', 'Ben', 'Cara'] }
const expense = (amount, extra = {}) => ({ description: 'Item', payer: 'Ann', amount, ...extra })

async function withTrip(fn) {
  await withApp(async call => {
    assert.equal((await call('POST', '/groups', trip)).status, 201)
    await fn(call)
  })
}

test('an expense of 4.35 is shown as 4.35, not 4.34', () => withTrip(async call => {
  const created = await call('POST', '/groups/trip/expenses', expense(4.35))
  assert.equal(created.status, 201)
  assert.equal(created.body.amount, 4.35)
  const listed = await call('GET', '/groups/trip/expenses')
  assert.equal(listed.body.expenses[0].amount, 4.35)
}))

test('a payment of 4.35 is shown as 4.35, not 4.34', () => withTrip(async call => {
  const created = await call('POST', '/groups/trip/payments', { from: 'Ben', to: 'Ann', amount: 4.35 })
  assert.equal(created.status, 201)
  assert.equal(created.body.amount, 4.35)
  const listed = await call('GET', '/groups/trip/payments')
  assert.equal(listed.body.payments[0].amount, 4.35)
}))

test('the data file stores 4.35 as 435 cents', async t => {
  const data = tempDataFile()
  const app = await startApp(data.file)
  t.after(async () => {
    await app.stop()
    data.cleanup()
  })
  await app.call('POST', '/groups', trip)
  assert.equal((await app.call('POST', '/groups/trip/expenses', expense(4.35))).status, 201)
  assert.equal(JSON.parse(readFileSync(data.file, 'utf8')).expenses[0].amount, 435)
})

test('a 10.00 expense gives the spare cent to the first person in the default split', () => withTrip(async call => {
  const res = await call('POST', '/groups/trip/expenses', expense(10))
  assert.deepEqual(res.body.shares, { Ann: 3.34, Ben: 3.33, Cara: 3.33 })
}))

test('a 10.00 expense gives the spare cent to the first person in a given split', () => withTrip(async call => {
  const res = await call('POST', '/groups/trip/expenses', expense(10, { split: ['Cara', 'Ann', 'Ben'] }))
  assert.deepEqual(res.body.shares, { Cara: 3.34, Ann: 3.33, Ben: 3.33 })
}))

test('balances after a 10.00 expense paid by Ann', () => withTrip(async call => {
  await call('POST', '/groups/trip/expenses', expense(10))
  const res = await call('GET', '/groups/trip/balances')
  assert.deepEqual(res.body, { balances: { Ann: 6.66, Ben: -3.33, Cara: -3.33 } })
}))

test('balances still add up to 0 cents after several uneven expenses', () => withTrip(async call => {
  await call('POST', '/groups/trip/expenses', expense(10))
  await call('POST', '/groups/trip/expenses', expense(0.01))
  await call('POST', '/groups/trip/expenses', expense(7.77, { split: ['Ben', 'Cara'] }))
  await call('POST', '/groups/trip/expenses', expense(100))
  const { balances } = (await call('GET', '/groups/trip/balances')).body
  const sum = Object.values(balances).reduce((a, b) => a + b, 0)
  assert.equal(Math.round(sum * 100), 0)
}))

test('settle-up after a 10.00 expense asks Ben and Cara for 3.33 each', () => withTrip(async call => {
  await call('POST', '/groups/trip/expenses', expense(10))
  const res = await call('GET', '/groups/trip/settle-up')
  assert.deepEqual(res.body, {
    payments: [{ from: 'Ben', to: 'Ann', amount: 3.33 }, { from: 'Cara', to: 'Ann', amount: 3.33 }],
  })
}))

function writeOldData(file) {
  const old = {
    groups: [trip],
    expenses: [{ id: 1, group: 'trip', description: 'Taxi', payer: 'Ann', amount: 434, split: ['Ann', 'Ben', 'Cara'] }],
    payments: [],
    nextExpenseId: 2,
    nextPaymentId: 1,
  }
  writeFileSync(file, JSON.stringify(old, null, 2) + '\n')
}

test('an existing data file is read as it is and not rewritten by a GET', async t => {
  const data = tempDataFile()
  t.after(data.cleanup)
  writeOldData(data.file)
  const before = readFileSync(data.file, 'utf8')
  const app = await startApp(data.file)
  t.after(() => app.stop())
  const res = await app.call('GET', '/groups/trip/expenses')
  assert.equal(res.body.expenses[0].amount, 4.34)
  assert.deepEqual(res.body.expenses[0].shares, { Ann: 1.45, Ben: 1.45, Cara: 1.44 })
  assert.equal(readFileSync(data.file, 'utf8'), before)
})

test('an existing 434 cent expense keeps its value after a new expense is added', async t => {
  const data = tempDataFile()
  t.after(data.cleanup)
  writeOldData(data.file)
  const app = await startApp(data.file)
  t.after(() => app.stop())
  assert.equal((await app.call('POST', '/groups/trip/expenses', expense(4.35))).status, 201)
  const saved = JSON.parse(readFileSync(data.file, 'utf8'))
  assert.equal(saved.expenses[0].amount, 434)
  assert.equal(saved.expenses[1].amount, 435)
})

